INSERT INTO simbolos (clave, nombre, descripcion, imagen, datos_curiosos) VALUES
  ('escudo','Escudo','Escudo Nacional','lib/simbolos patrios/escudo.jpg','["El Escudo Nacional fue creado en 1825 y muestra dos océanos, un volcán, un arcoíris y un sol.", "Lleva la frase \\"República de Honduras, Libre, Soberana e Independiente\\".", "En su parte superior aparece un gorro frigio, símbolo de la libertad."]'),
  ('bandera','Bandera','Pabellón Nacional','lib/simbolos patrios/bandera.jpg','["El azul de la bandera representa los dos océanos que rodean a Honduras: el Atlántico y el Pacífico.", "El blanco simboliza la paz, y las 5 estrellas representan las provincias de Centroamérica.", "En 2022 el tono de la franja azul cambió al azul cielo turquesa."]'),
  ('flor','Orquídea','Flor Nacional','lib/simbolos patrios/flor.jpg','["La flor nacional es la orquídea Rhyncholaelia digbyana, declarada símbolo nacional en 1969.", "Su perfume es más intenso al atardecer y durante la noche.", "Es una de las orquídeas más grandes y llamativas de Honduras."]'),
  ('venado','Venado','Mamífero Nacional','lib/simbolos patrios/venado.jpg','["El venado de cola blanca es el mamífero nacional de Honduras desde 1993.", "Levanta su cola blanca al correr para avisar a los demás de un peligro.", "Habita bosques y llanuras de casi todo el país."]'),
  ('cafe','Café','Producto Nacional','lib/simbolos patrios/cafe.jpg','["Honduras es uno de los mayores productores de café de Centroamérica.", "El café es uno de los principales productos de exportación del país.", "Se cultiva en las montañas de Copán, Marcala y la zona occidental."]'),
  ('cuestionario','Cuestionario Cívico','Cuestionario Cívico','lib/simbolos patrios/cuestionario.jpg','["El Cuestionario Cívico reúne los conocimientos básicos sobre los símbolos y deberes de Honduras.", "Enseña fechas patrias como el 15 de septiembre, Día de la Independencia (1821).", "Ayuda a los estudiantes a conocer y respetar los símbolos nacionales."]'),
  ('guacamaya','Guacamaya','Ave Nacional','lib/simbolos patrios/guacamaya.jpg','["La guacamaya roja o \\"guara\\" es el ave nacional de Honduras desde 1993.", "Puede vivir más de 50 años y suele formar pareja de por vida.", "Habita las selvas del norte, como La Mosquitia y el Parque Nacional Cusuco."]'),
  ('banano','Banano','Fruto Tropical','lib/simbolos patrios/banano.jpg','["El banano es uno de los principales productos de exportación de Honduras.", "Su cultivo impulsó el desarrollo económico del país durante el siglo XX.", "Se produce sobre todo en el litoral del Caribe, en la zona del Valle de Sula."]'),
  ('mapa','Mapa','Mapa de Honduras','lib/simbolos patrios/mapa.jpg','["Honduras está en el centro de Centroamérica y limita con Guatemala, El Salvador y Nicaragua.", "Tiene costas en dos océanos: el Atlántico (mar Caribe) y el Pacífico.", "Su punto más alto es el Cerro Las Minas, con unos 2,870 metros."]'),
  ('cacique_lempira','Cacique Lempira','Héroe Nacional','lib/simbolos patrios/cacique lempira.jpg','["Lempira fue un líder indígena lenca que luchó contra los españoles entre 1537 y 1538.", "Su nombre significa \\"Señor de la Sierra\\".", "Es el héroe nacional de Honduras y da nombre a la moneda del país."]'),
  ('francisco_morazan','Francisco Morazán','Prócer Nacional','lib/simbolos patrios/francisco morazan.jpg','["Francisco Morazán nació en Tegucigalpa en 1792.", "Fue presidente de la República Federal de Centro América.", "Impulsó la unión de los países centroamericanos y grandes reformas liberales."]'),
  ('jose_trinidad_cabanas','José Trinidad Cabañas','Prócer Nacional','lib/simbolos patrios/jose trinidad cabañas.jpg','["José Trinidad Cabañas fue presidente de Honduras entre 1852 y 1855.", "Se destacó como militar y estadista de gran honradez.", "Es recordado como ejemplo de servicio y honestidad para el país."]'),
  ('lempira','Lempira','Moneda Nacional','lib/simbolos patrios/lempira.jpg','["El lempira es la moneda de Honduras y se divide en 100 centavos.", "Fue creada en 1931 y lleva el nombre del cacique Lempira.", "Su símbolo es la letra \\"L\\" y sus billetes muestran próceres y paisajes del país."]')
